<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Form 945-V, Payment Voucher</title>
    <style>
        body {
            font-family: Arial, Helvetica, sans-serif;
            margin: 0;
            padding: 20px;
            display: flex;
            justify-content: center;
            background-color: #f5f5f5;
        }
        .document-container {
            background-color: #ffffff;
            width: 850px;
            max-width: 100%;
            padding: 40px;
            box-shadow: 0 0 10px rgba(0,0,0,0.1);
            color: black;
            box-sizing: border-box;
        }
        .main-header {
            border-top: 4px solid black;
            border-bottom: 2px solid black;
            padding: 8px 0;
            margin-bottom: 15px;
        }
        .main-header h1 {
            margin: 0;
            font-size: 26px;
            line-height: 1.2;
        }
        .instructions-container {
            display: flex;
            gap: 30px;
        }
        .column {
            flex: 1;
        }
        h2 {
            font-size: 16px;
            margin: 0 0 8px 0;
            padding: 0;
        }
        p {
            font-size: 12.5px;
            line-height: 1.35;
            margin: 0 0 10px 0;
            text-align: justify;
        }
        ul {
            margin: 0 0 10px 0;
            padding-left: 18px;
        }
        li {
            font-size: 12.5px;
            line-height: 1.35;
            margin-bottom: 6px;
            text-align: justify;
        }
        .bold-start {
            font-weight: bold;
        }
